def _coupledtau_terminal_theorems(gates):
    """Exact anchors: the coupled recursion and its bilinear tau
    corollary, the terminal reduction and consequence gate, the
    corner-ray normal form, and the positive-prefix firewall PSD
    theorem with its signed must-fail."""
    import sympy as sp

    def chk(name, ok, detail=""):
        gates.append(bool(ok))
        print("  [%s] %s%s" % ("PASS" if ok else "FAIL", name,
                               ("  -- " + detail) if detail else ""),
              flush=True)

