    bilinear = sp.simplify(taug * tau1 - taug1 * tau
                           - (c * F) ** 2 * tau ** 2)
    ok2s = (bilinear == 0)
    # frozen rational chain (5 steps): c_n, h_n, F_n and budget B
    cs = [_Fr(2, 3), _Fr(3, 5), _Fr(7, 4), _Fr(1, 2), _Fr(5, 6)]
    hs = [_Fr(4, 7), _Fr(9, 5), _Fr(2, 3), _Fr(11, 8), _Fr(3, 2)]
    Fs = [_Fr(1, 3), _Fr(-2, 5), _Fr(5, 7), _Fr(-1, 4), _Fr(2, 9)]
    B = _Fr(31, 6)
    tau_n = hs[0]
    taug_n = hs[0] * B - Fs[0] ** 2
    ok2r = True
    rho_sum = Fs[0] ** 2 / hs[0]
    for n in range(1, 5):
        an = cs[n] ** 2 * hs[n]
        bn = -(cs[n] * Fs[n]) ** 2
        tau_np, taug_np = an * tau_n, an * taug_n + bn * tau_n
        ok2r = ok2r and (taug_n * tau_np - taug_np * tau_n
                         == (cs[n] * Fs[n]) ** 2 * tau_n ** 2)
        ok2r = ok2r and (taug_np / tau_np
                         == taug_n / tau_n - Fs[n] ** 2 / hs[n])
        rho_sum += Fs[n] ** 2 / hs[n]
        tau_n, taug_n = tau_np, taug_np
    ok2r = ok2r and (taug_n / tau_n == B - rho_sum)   # telescoped
    chk("S0.2-bilinear-tau-form-exact", ok2s and ok2r,
        "tau^aug_n tau_{n+1} - tau^aug_{n+1} tau_n = (c_n F_n)^2 "
        "tau_n^2 EXACT (sympy identity + every step of the frozen "
        "5-step rational chain), and the chain telescopes to D_N = "
        "B - Sum rho_n exactly -- the drain increment is a positive "
        "tau cross-ratio: the r257 recursion and the bilinear "
        "Hirota-type form are ONE statement")

    # --- S0.3 the terminal reduction + the consequence gate
    S2, rhoN, t = sp.symbols("S2 rhoN t")
    Bdef = S2 + sp.Rational(5, 7)                     # r243 a4 def
    DN = Bdef - (S2 + rhoN)               # B - S_{N-1}, S_{N-1} =
    ok3s = sp.simplify(                   # S_{N-2} + rho_{N-1}
        DN - (sp.Rational(5, 7) - rhoN)) == 0
    qN = rhoN / sp.Rational(5, 7)
    ok3g = sp.simplify(DN - sp.Rational(5, 7) * (1 - qN)) == 0
    # exact rationals, both truth values
    ok3r = True
    for rho_v, positive in ((_Fr(2, 7), True), (_Fr(6, 7), False)):
        margin = _Fr(5, 7) - rho_v
        q_v = rho_v / _Fr(5, 7)
        ok3r = ok3r and ((margin > 0) == positive == (q_v < 1))
    chk("S0.3-terminal-consequence-gate", ok3s and ok3g and ok3r,
        "with B = S_{N-2} + 5/7 (by construction, r243 a4): D_N = "
        "5/7 - rho_{N-1} and margin > 0 iff q_N = rho_{N-1}/(5/7) "
        "< 1 (symbolic identity + exact rationals in both truth "
        "values) -- the entire fiber positivity is ONE terminal "
        "inequality; the 5/7 itself stays typed FLOOR_IMPORTED "
        "(inverted r241 floor of the measured min h_{N-1}/F_{N-1}^2 "
        "= 1.4278), its source-pure derivation OPEN")

    # --- S0.4 the corner-ray / t* normal form
    Dt = (S2 + t * sp.Rational(5, 7)) - (S2 + rhoN)
    slope = sp.diff(Dt, t)
    root = sp.solve(sp.Eq(Dt, 0), t)[0]
    ok4 = (sp.simplify(slope - sp.Rational(5, 7)) == 0
           and sp.simplify(root - qN) == 0
           and sp.simplify(sp.diff(Dt, t, 2)) == 0)
