    # --- S0.5 the positive-prefix firewall PSD theorem
    def hankel_minor_dets(nodes, weights, p_hi):
        moms = [sum(w * x ** k for x, w in zip(nodes, weights))
                for k in range(2 * p_hi)]
        dets = []
        for p in range(1, p_hi + 1):
            A = [[moms[i + j] for j in range(p)] for i in range(p)]
            dets.append(_det_frac(A))
        return dets

    def _det_frac(A):
        A = [row[:] for row in A]
        n = len(A)
        det = _Fr(1)
        for cidx in range(n):
            piv = None
            for r in range(cidx, n):
                if A[r][cidx] != 0:
                    piv = r
                    break
            if piv is None:
                return _Fr(0)
            if piv != cidx:
                A[cidx], A[piv] = A[piv], A[cidx]
                det = -det
            det *= A[cidx][cidx]
            inv = _Fr(1) / A[cidx][cidx]
            for r in range(cidx + 1, n):
                f = A[r][cidx] * inv
                if f:
                    A[r] = [x - f * y for x, y in zip(A[r], A[cidx])]
        return det

    def _solve_frac(G, rhs):
        n = len(rhs)
        M = [G[i][:] + [rhs[i]] for i in range(n)]
        for cidx in range(n):
            piv = next(r for r in range(cidx, n) if M[r][cidx] != 0)
            M[cidx], M[piv] = M[piv], M[cidx]
            inv = _Fr(1) / M[cidx][cidx]
            M[cidx] = [x * inv for x in M[cidx]]
            for r in range(n):
                if r != cidx and M[r][cidx]:
                    f = M[r][cidx]
                    M[r] = [x - f * y for x, y in zip(M[r], M[cidx])]
        return [M[i][n] for i in range(n)]

    # positive control: 5 positive rational atoms -> POSITIVE_PREFIX
    xsp = [_Fr(-4, 5), _Fr(-1, 3), _Fr(1, 6), _Fr(1, 2), _Fr(9, 10)]
    wsp = [_Fr(2, 5), _Fr(1, 2), _Fr(3, 7), _Fr(1, 3), _Fr(2, 7)]
    dets_pos = hankel_minor_dets(xsp, wsp, 5)
    hs_pos = [dets_pos[0]] + [dets_pos[i] / dets_pos[i - 1]
                              for i in range(1, 5)]
    ok5a = all(d > 0 for d in dets_pos) and all(h > 0 for h in hs_pos)
    # signed measure mu - nu: the h-chain flips inside the window ->
    # INDEFINITE_CONTINUATION with a well-defined maximal positive
    # prefix p_max (frozen witness, verified exactly at freeze time)
    xss = xsp + [_Fr(6, 5), _Fr(13, 10)]
    wss = wsp + [-_Fr(9, 100), -_Fr(4, 380)]
